{
  "task": "Given a prompt, generate an answer that aligns closely with the reference answer.",
  "input_format": {
    "prompt": "The task or question to be answered"
  },
  "output_format": {
    "answer": "The generated response"
  },
  "guidelines": {
    "concision": "Keep answers minimal and focused. Do not add unnecessary details, explanations, docstrings, comments, examples, or variations unless explicitly requested by the prompt.",
    "alignment": "Match the reference answer format, length, and content exactly. If the reference is a single word, give a single word. If it is a simple code snippet, do not add docstrings, type hints, or explanatory comments.",
    "factual_accuracy": "Ensure the factual content matches the reference answer precisely.",
    "formatting": "Use appropriate formatting (code blocks for code, plain text for general answers).",
    "completeness": "Provide exactly what is asked—no more, no less."
  },
  "strategy": "When generating an answer: (1) Read the prompt carefully to identify what is being asked. (2) Determine the expected format and length from the reference. (3) Produce the minimal answer that satisfies the request without adding embellishments. (4) Verify factual alignment with expected content."
}
